// CSD_RATIONALE_BEGIN
// Multi-span adaptive CSD for symbolic GSM reasoning.
// State: (generated, insideConstrainedOut, currentConstrainedOut, steps).
// Outside spans: generate freely with UnconstrainedStep; detect "<<" in
// rendered output to enter constrained mode and reset currentConstrainedOut=[].
// Inside spans: first try CloseSpanIfComplete (costs 1 if the span is already
// a complete parse, 0 otherwise); on a no-close step, call
// AdaptiveConstrainedStep with caller-supplied validTokenGroups to produce the
// next parser-valid token, then commit it via AppendConstrainedToken.
// Multiple <<...>> spans may appear: intermediate symbolic sub-expressions
// during chain-of-thought and the final answer expression. The loop handles
// all of them uniformly.
// AppendTaskGuidance at the top reinforces "wrap every symbolic expression in
// << >>; final answer is <<expr>>" and keeps the model on the required surface.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)):
//   Outside branch: insideConstrainedOut flips to true only when
//     RenderedEndsWith(generated,"<<") holds; currentConstrainedOut is set to []
//     which is valid by the precondition parser.IsValidPrefix([]). Otherwise the
//     implication is vacuous.
//   CloseSpanIfComplete (closed=true): helper postconditions give
//     !insideConstrainedOut and currentConstrainedOut==[], making the implication
//     vacuously true.
//   CloseSpanIfComplete (closed=false): state unchanged, invariant holds by IH.
//   AdaptiveConstrainedStep branch: returns EOS or a parser-valid extension
//     token; AppendConstrainedToken extends currentConstrainedOut by that token
//     and its postcondition guarantees parser.IsValidPrefix(currentConstrainedOut).
//
// progress (|generated| <= |generatedPrefix| + steps):
//   Outside branch: appends at most one token (next, when not EOS) and
//     increments steps by 1, so bound is preserved.
//   CloseSpanIfComplete (closed=true): appends ">>" (one token) and steps
//     increments by 1; bound preserved.
//   CloseSpanIfComplete (closed=false) + AdaptiveConstrainedStep: cost of
//     CloseSpanIfComplete is 0; AdaptiveConstrainedStep costs 1 step, and
//     AppendConstrainedToken appends at most one visible token. Steps already
//     incremented by 1 before this sub-branch, so total cost per iteration = 1,
//     visible growth <= 1. Bound preserved.
//   EOS break: no appends; steps reflects prior increments.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Wrap every intermediate symbolic expression in << >>. " +
  "End with: The final answer is <<expr>> where expr uses only numbers, the " +
  "problem variables, and the operations +, -, /, //, %, (), int().");

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else {
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, 12, eosToken
      );
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

cost := steps;

